Liberação range

async function adicionarIPs() {
 console.log("Iniciando a adição de IPs...");

 for (let i = 1; i <= 254; i++) {
 let ip = "192.168.1." + i;

 let input = document.querySelector('input[formcontrolname="ip"]');

 if (!input) {
 console.error("Campo de input não encontrado. Verifique se a página mudou.");
 break;
 }
 input.value = ip;

 input.dispatchEvent(new Event('input', { bubbles: true }));

 await new Promise(r => setTimeout(r, 200));

 let botao = document.querySelector('button.add-ip-button');

 if (botao && !botao.disabled) {
 botao.click();
 console.log("Adicionado: " + ip);
 } else {
 console.warn("Botão estava desabilitado para o IP: " + ip);
 }
 await new Promise(r => setTimeout(r, 1000));
 }
 console.log("Processo finalizado!");
}
// Executa a função
adicionarIPs();

Liberação lista Ips

async function adicionarListaIPs() {
 // 1. Defina sua lista de IPs aqui
 const listaIPs = [
 "203.0.113.1", "203.0.113.15", "198.51.100.42", "198.51.100.99", "192.0.2.5",
 "192.0.2.18", "10.15.22.4", "10.15.22.99", "172.31.5.8", "172.31.5.21",
 "8.8.8.8", "8.8.4.4", "1.1.1.1", "1.0.0.1", "9.9.9.9",
 "142.250.190.14", "142.250.190.46", "104.21.55.1", "104.21.55.2", "172.67.10.1",
 "18.20.50.11", "18.20.50.22", "54.10.20.30", "54.10.20.40", "3.3.3.3",
 "4.4.4.4", "15.15.15.15", "16.16.16.16", "23.23.23.23", "42.42.42.42"
 ];
 console.log(`Iniciando a adição de ${listaIPs.length} IPs...`);

 // O loop 'for...of' percorre cada IP dentro da lista
 for (const ip of listaIPs) { 

 // 2. Encontra o campo de texto
 let input = document.querySelector('input[formcontrolname="ip"]');

 if (!input) {
 console.error("Campo de input não encontrado. O script será interrompido.");
 break;
 }
 // Insere o IP da vez
 input.value = ip;

 // 3. Dispara evento para o Angular reconhecer a digitação e habilitar o botão
 input.dispatchEvent(new Event('input', { bubbles: true }));

 // Pausa de 300ms para o sistema validar o IP
 await new Promise(r => setTimeout(r, 300));

 // 4. Encontra o botão de adicionar e clica
 let botao = document.querySelector('button.add-ip-button');

 if (botao && !botao.disabled) {
 botao.click();
 console.log("Adicionado: " + ip);
 } else {
 console.warn("Botão estava desabilitado para o IP: " + ip);
 }

 // 5. Pausa de 1 segundo entre cada IP para não sobrecarregar o sistema
 await new Promise(r => setTimeout(r, 1000));
 }

 console.log("Processo finalizado!");
}
// Executa a função
adicionarListaIPs();
